{"output":""""
Result type for functional error handling.

Provides Success/Failure pattern for explicit error handling without exceptions.

Usage:
    from kris_core.result import Result, Success, Failure

    def parse_document(path: Path) -> Result[Document, KrisError]:
        try:
            doc = do_parse(path)
            return Success(doc)
        except ParseError as e:
            return Failure(KrisError(ErrorCode.PDF_PARSE_ERROR, str(e)))

    # Pattern matching
    match result:
        case Success(value):
            print(f"Got: {value}")
        case Failure(error):
            print(f"Error: {error}")
"""

from collections.abc import Callable
from dataclasses import dataclass
from typing import Any, Generic, NoReturn, TypeVar

T = TypeVar("T")
E = TypeVar("E")
U = TypeVar("U")


@dataclass(frozen=True)
class Success(Generic[T]):
    """Represents a successful result containing a value."""

    value: T

    def is_success(self) -> bool:
        """Return True if this is a Success."""
        return True

    def is_failure(self) -> bool:
        """Return False if this is a Success."""
        return False

    def map(self, fn: Callable[[T], U]) -> "Success[U]":
        """Apply a function to the success value."""
        return Success(fn(self.value))

    def unwrap(self) -> T:
        """Get the value, raises if called on Failure."""
        return self.value

    def unwrap_or(self, default: T) -> T:  # noqa: ARG002
        """Get the value or return default (default is unused for Success)."""
        return self.value


@dataclass(frozen=True)
class Failure(Generic[E]):
    """Represents a failed result containing an error."""

    error: E

    def is_success(self) -> bool:
        """Return False if this is a Failure."""
        return False

    def is_failure(self) -> bool:
        """Return True if this is a Failure."""
        return True

    def map(self, fn: Callable[[Any], Any]) -> "Failure[E]":  # noqa: ARG002
        """Return self unchanged (no value to map)."""
        return self

    def unwrap(self) -> NoReturn:
        """Raises ValueError since there's no value."""
        raise ValueError(f"Called unwrap on Failure: {self.error}")

    def unwrap_or(self, default: T) -> T:
        """Return default since there's no value."""
        return default


# Type alias for Result
Result = Success[T] | Failure[E]


def is_success(result: Result[T, E]) -> bool:
    """Check if result is a Success."""
    return isinstance(result, Success)


def is_failure(result: Result[T, E]) -> bool:
    """Check if result is a Failure."""
    return isinstance(result, Failure)
