import pytest

from kris_core.errors import ErrorCode, KrisError


class TestErrorCode:
    """Tests for the ErrorCode enum."""

    def test_error_codes_have_string_values(self) -> None:
        """All error codes should have string values."""
        for code in ErrorCode:
            assert isinstance(code.value, str)

    def test_pdf_parse_error_exists(self) -> None:
        """PDF_PARSE_ERROR should be defined."""
        assert ErrorCode.PDF_PARSE_ERROR.value == "pdf_parse_error"

    def test_parameter_not_found_exists(self) -> None:
        """PARAMETER_NOT_FOUND should be defined."""
        assert ErrorCode.PARAMETER_NOT_FOUND.value == "parameter_not_found"

    def test_invalid_profile_exists(self) -> None:
        """INVALID_PROFILE should be defined."""
        assert ErrorCode.INVALID_PROFILE.value == "invalid_profile"

    def test_extraction_failed_exists(self) -> None:
        """EXTRACTION_FAILED should be defined."""
        assert ErrorCode.EXTRACTION_FAILED.value == "extraction_failed"


class TestKrisError:
    """Tests for the KrisError dataclass."""

    def test_kris_error_creation(self) -> None:
        """Should be able to create KrisError with code and message."""
        error = KrisError(
            code=ErrorCode.PDF_PARSE_ERROR,
            message="Failed to parse PDF",
        )
        assert error.code == ErrorCode.PDF_PARSE_ERROR
        assert error.message == "Failed to parse PDF"
        assert error.details == {}

    def test_kris_error_with_details(self) -> None:
        """Should be able to create KrisError with details."""
        error = KrisError(
            code=ErrorCode.PDF_PARSE_ERROR,
            message="Failed to parse PDF",
            details={"path": "/test.pdf", "page": 5},
        )
        assert error.details == {"path": "/test.pdf", "page": 5}

    def test_kris_error_is_frozen(self) -> None:
        """KrisError should be immutable."""
        error = KrisError(
            code=ErrorCode.UNKNOWN_ERROR,
            message="Test",
        )
        with pytest.raises(AttributeError):
            error.message = "Changed"  # type: ignore[misc]

    def test_kris_error_str_without_details(self) -> None:
        """__str__ should format error without details."""
        error = KrisError(
            code=ErrorCode.PDF_PARSE_ERROR,
            message="Parse failed",
        )
        assert str(error) == "[pdf_parse_error] Parse failed"

    def test_kris_error_str_with_details(self) -> None:
        """__str__ should format error with details."""
        error = KrisError(
            code=ErrorCode.PDF_PARSE_ERROR,
            message="Parse failed",
            details={"path": "/test.pdf"},
        )
        assert "[pdf_parse_error] Parse failed" in str(error)
        assert "path" in str(error)

    def test_kris_error_to_dict(self) -> None:
        """to_dict() should convert error to dictionary."""
        error = KrisError(
            code=ErrorCode.EXTRACTION_FAILED,
            message="Extraction failed",
            details={"param": "test"},
        )
        result = error.to_dict()
        assert result == {
            "code": "extraction_failed",
            "message": "Extraction failed",
            "details": {"param": "test"},
        }
